cd /app && perl << 'PERLEOF'
use strict;
use warnings;

# Read sequences
my %sequences;
my $current_seq;
my $current_data = '';

open my $fh, '<', 'sequences.fasta' or die "Cannot open sequences.fasta: $!";
while (my $line = <$fh>) {
    chomp $line;
    if ($line =~ /^>(.+)$/) {
        if ($current_seq) {
            $sequences{$current_seq} = $current_data;
        }
        $current_seq = $1;
        $current_data = '';
    } else {
        $current_data .= $line;
    }
}
if ($current_seq) {
    $sequences{$current_seq} = $current_data;
}
close $fh;

# Golden Gate primer design with BsaI-HF v2
# BsaI recognizes GGTCTC(N)^(N) and cuts to leave the N overhang
# Forward primer format: 5' [left_overhang] GGTCTC N [annealing_region] 3'
# Reverse primer format: 5' [right_overhang_rc] GGTCTC N [annealing_region_rc] 3'

# For a 4-part circular assembly, we need compatible overhangs
# Let's use simple overhangs that are easy to validate

sub reverse_complement {
    my ($seq) = @_;
    $seq = reverse($seq);
    $seq =~ tr/ATGCatgc/TACGTACG/;
    return $seq;
}

sub get_tm {
    my ($seq) = @_;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $seq 2>&1`;
    chomp $result;
    return $result if $result =~ /^\d/;
    return undef;
}

# Parts and design parameters
my @parts = ('input', 'egfp', 'flag', 'snap');

# Design overhangs for circular assembly: input->egfp->flag->snap->input
# Each junction needs compatible overhangs
my %left_overhang = (
    'input' => 'AATT',
    'egfp'  => 'GCGC',
    'flag'  => 'GATA',
    'snap'  => 'CGTA',
);

my %right_overhang = (
    'input' => 'CGTA',
    'egfp'  => 'AATT',
    'flag'  => 'GCGC',
    'snap'  => 'GATA',
);

# Try to find good annealing regions
my %primers;

foreach my $part (@parts) {
    my $seq = $sequences{$part};

    # Forward primer: bind to start, append left overhang to final PCR product
    # Reverse primer: bind to end (rc), append right overhang to final PCR product

    # Forward primer structure: [left_overhang] GGTCTC [N] [annealing_start]
    # Reverse primer structure: [right_overhang_rc] GGTCTC [N] [annealing_end_rc]

    # We want annealing region to have Tm 58-72
    # Start with 20bp annealing regions

    my $left_oh = $left_overhang{$part};
    my $right_oh = $right_overhang{$part};

    # Try different annealing lengths (15-45bp)
    for my $alen (20, 22, 24, 25, 26) {
        my $fwd_anneal = substr($seq, 0, $alen);
        my $rev_anneal = substr($seq, -$alen);
        my $rev_anneal_rc = reverse_complement($rev_anneal);

        my $fwd_tm = get_tm($fwd_anneal);
        my $rev_tm = get_tm($rev_anneal_rc);

        if ($fwd_tm && $rev_tm) {
            $fwd_tm = sprintf("%.2f", $fwd_tm);
            $rev_tm = sprintf("%.2f", $rev_tm);
            my $diff = abs($fwd_tm - $rev_tm);

            if ($fwd_tm >= 58 && $fwd_tm <= 72 && $rev_tm >= 58 && $rev_tm <= 72 && $diff <= 5) {
                print "$part (annealing=$alen bp):\n";
                print "  Fwd Tm=$fwd_tm, Rev Tm=$rev_tm, diff=$diff\n";
                print "  Fwd anneal: $fwd_anneal\n";
                print "  Rev anneal: $rev_anneal_rc\n";

                # Store this design
                $primers{$part} = {
                    'fwd_anneal' => $fwd_anneal,
                    'rev_anneal_rc' => $rev_anneal_rc,
                    'alen' => $alen,
                    'fwd_tm' => $fwd_tm,
                    'rev_tm' => $rev_tm,
                    'left_oh' => $left_oh,
                    'right_oh' => $right_oh,
                };
                last;
            }
        }
    }
}

print "\n=== PRIMER SUMMARY ===\n";
foreach my $part (@parts) {
    if ($primers{$part}) {
        my $p = $primers{$part};
        my $left_oh = $p->{'left_oh'};
        my $right_oh = $p->{'right_oh'};

        # Construct full primers
        my $fwd_full = $left_oh . 'GGTCTC' . 'A' . $p->{'fwd_anneal'};
        my $rev_full = reverse_complement($right_oh . 'GGTCTC' . 'A' . $p->{'rev_anneal_rc'});

        print "\n$part:\n";
        print "  FWD: $fwd_full\n";
        print "  REV: $rev_full\n";
        print "  Fwd Tm: " . $p->{'fwd_tm'} . "°C\n";
        print "  Rev Tm: " . $p->{'rev_tm'} . "°C\n";
    }
}
