cd /app && perl << 'PERLEOF'
use strict;
use warnings;

# Read sequences
my %sequences;
my $current_seq;
my $current_data = '';

open my $fh, '<', 'sequences.fasta' or die "Cannot open sequences.fasta: $!";
while (my $line = <$fh>) {
    chomp $line;
    if ($line =~ /^>(.+)$/) {
        if ($current_seq) {
            $sequences{$current_seq} = $current_data;
        }
        $current_seq = $1;
        $current_data = '';
    } else {
        $current_data .= $line;
    }
}
if ($current_seq) {
    $sequences{$current_seq} = $current_data;
}
close $fh;

sub reverse_complement {
    my ($seq) = @_;
    $seq = reverse($seq);
    $seq =~ tr/ATGCatgc/TACGTACG/;
    return $seq;
}

sub get_tm {
    my ($seq) = @_;
    return undef if length($seq) < 2 || length($seq) > 36;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $seq 2>&1`;
    chomp $result;
    return $result if $result =~ /^[\d.]+$/;
    return undef;
}

my @parts = ('input', 'egfp', 'flag', 'snap');
my %primers;

# Try to find good primers for each part
foreach my $part (@parts) {
    my $seq = $sequences{$part};
    my $found = 0;

    # Try annealing lengths from 15 to 45
    for my $alen (15..45) {
        last if $found;

        my $fwd_anneal = substr($seq, 0, $alen);
        my $rev_template = substr($seq, -$alen);
        my $rev_anneal = reverse_complement($rev_template);

        my $fwd_tm = get_tm($fwd_anneal);
        my $rev_tm = get_tm($rev_anneal);

        next unless $fwd_tm && $rev_tm;

        $fwd_tm = sprintf("%.2f", $fwd_tm);
        $rev_tm = sprintf("%.2f", $rev_tm);
        my $diff = abs($fwd_tm - $rev_tm);

        if ($fwd_tm >= 58 && $fwd_tm <= 72 && 
            $rev_tm >= 58 && $rev_tm <= 72 && 
            $diff <= 5) {

            $primers{$part} = {
                'fwd_anneal' => $fwd_anneal,
                'rev_anneal' => $rev_anneal,
                'alen' => $alen,
                'fwd_tm' => $fwd_tm,
                'rev_tm' => $rev_tm,
            };
            $found = 1;
            print "Found: $part (alen=$alen, fwd_tm=$fwd_tm, rev_tm=$rev_tm)\n";
        }
    }

    unless ($found) {
        print "FAILED: $part\n";
    }
}

# Now add BsaI overhangs
# BsaI site format: GGTCTC(N)^(N) where ^ is the cut site
# The primer will have: [overhang] GGTCTC N [annealing_region]
# After PCR, the part will have GGTCTC sites with 4bp overhangs

my %left_oh = ('input'=>'AATT', 'egfp'=>'GCGC', 'flag'=>'GATA', 'snap'=>'CGTA');
my %right_oh = ('input'=>'CGTA', 'egfp'=>'AATT', 'flag'=>'GCGC', 'snap'=>'GATA');

print "\n=== FINAL PRIMERS ===\n";
my $primer_count = 0;

foreach my $part (@parts) {
    if ($primers{$part}) {
        $primer_count += 2;
        my $p = $primers{$part};
        my $left_oh = $left_oh{$part};
        my $right_oh = $right_oh{$part};

        # Forward: [left_overhang] GGTCTC [separator] [annealing_region]
        my $fwd_full = $left_oh . 'GGTCTC' . 'A' . $p->{'fwd_anneal'};

        # Reverse: [right_overhang_rc] GGTCTC [separator] [annealing_region]
        # The reverse primer binds to the template's reverse complement
        my $right_oh_rc = reverse_complement($right_oh);
        my $rev_full = $right_oh_rc . 'GGTCTC' . 'A' . $p->{'rev_anneal'};

        print ">$part" . "_fwd\n$fwd_full\n";
        print ">$part" . "_rev\n$rev_full\n";
    }
}

print "\nTotal primers: $primer_count\n";
PERLEOF

